"""Offline chunk + embed pipeline (not on the serving path).

Used by the CI vector-index build and the evaluator.
The copilot's serving path does **not** import this.
"""

from typing import Any, Dict, Iterable, List

import structlog

from rasa.builder.document_retrieval.local.chunking import Chunk, Chunker
from rasa.builder.document_retrieval.local.config import ChunkingConfig
from rasa.builder.document_retrieval.local.embedding import Embedder
from rasa.builder.document_retrieval.local.index import LocalIndex
from rasa.builder.document_retrieval.source import SourceDocument

structlogger = structlog.get_logger()


def _build_chunks(documents: Iterable[SourceDocument]) -> List[Chunk]:
    """Chunk every document, tagging each chunk with its document's topic."""
    chunker = Chunker(ChunkingConfig())
    chunks: List[Chunk] = []
    for document in documents:
        # Topic is corpus-provided metadata
        topic = str(document.metadata.get("topic", ""))
        chunks.extend(chunker.chunk_document(document, topic))
    return chunks


def build_chunk_rows(
    documents: List[SourceDocument], embedder: Embedder
) -> List[Dict[str, Any]]:
    """Chunk + embed the given documents."""
    chunks = _build_chunks(documents)
    if not chunks:
        return []
    vectors = embedder.encode([c.text for c in chunks])
    return [chunk.to_row(vector) for chunk, vector in zip(chunks, vectors)]


def sync_index(
    index: LocalIndex,
    documents: List[SourceDocument],
    corpus_version: str,
    embedder: Embedder,
) -> None:
    """Fill ``index`` from ``documents``, embedding them here.

    Required for evaluator, might be refactored in future. Does nothing when the
    index already holds ``corpus_version``. The old contents are only replaced
    once the new rows are embedded, so a failed build leaves them in place.

    Args:
        index: The index to fill.
        documents: The full corpus (whole documents; chunked here).
        corpus_version: Opaque snapshot id; stamped into the index metadata.
        embedder: Embedder used to vectorize chunks (shared with the retriever).

    Raises:
        ValueError: If ``documents`` is empty or produces no chunks.
    """
    if not documents:
        raise ValueError("Cannot build an index from an empty document set.")

    if index.is_current(corpus_version):
        structlogger.info(
            "local_index.build_noop",
            corpus=index.corpus,
            key=index.key,
            document_count=len(documents),
        )
        return

    rows = build_chunk_rows(documents, embedder)
    if not rows:
        raise ValueError(f"No chunks produced from {len(documents)} source documents.")
    index.replace(
        rows,
        corpus_version=corpus_version,
        document_count=len(documents),
        embed_dim=embedder.dim,
    )
    structlogger.info(
        "local_index.built",
        corpus=index.corpus,
        key=index.key,
        document_count=len(documents),
        chunk_count=len(rows),
        embed_dim=embedder.dim,
    )
